-- ### 前端兼容的用户性别字典
select 1761500000000000016, '用户性别', 'sys_user_sex', 1761000000000000103, 1761100000000000001, sysdate(), null, null, '管理端用户性别字典' from dual
where not exists (select 1 from sys_dict_type where dict_type = 'sys_user_sex');
select 1761600000000000060, 1, 'dict.sys_user_sex.male', '0', 'sys_user_sex', '', '', 'Y', 1761000000000000103, 1761100000000000001, sysdate(), null, null, '性别男' from dual
where not exists (select 1 from sys_dict_data where dict_type = 'sys_user_sex' and dict_value = '0');
select 1761600000000000061, 2, 'dict.sys_user_sex.female', '1', 'sys_user_sex', '', '', 'N', 1761000000000000103, 1761100000000000001, sysdate(), null, null, '性别女' from dual
where not exists (select 1 from sys_dict_data where dict_type = 'sys_user_sex' and dict_value = '1');
select 1761600000000000062, 3, 'dict.sys_user_sex.unknown', '2', 'sys_user_sex', '', '', 'N', 1761000000000000103, 1761100000000000001, sysdate(), null, null, '性别未知' from dual
where not exists (select 1 from sys_dict_data where dict_type = 'sys_user_sex' and dict_value = '2');
